<script setup>
import { computed } from 'vue';
import { PLAN_STATE,fdate } from '../../lib/client-info';
const props=defineProps({bundle:Object,metrics:Object});
const counts=computed(()=>{const states=props.metrics.planView;return[['📋','Plans',states.length],['▲','On track',states.filter(row=>row.h.state==='ok').length],['▼','Behind pace',states.filter(row=>row.h.state==='behind').length],['⛔','Past end date',states.filter(row=>row.h.state==='overdue').length],['🏁','Completed',states.filter(row=>row.h.state==='done').length],['📦','Completion',props.metrics.completion+'%']];});
</script>
<template><div><div class="c3-kpis"><div v-for="row in counts" :key="row[1]" class="c3-kpi"><span class="c3-kpi-ic">{{ row[0] }}</span><div><small>{{ row[1] }}</small><b>{{ row[2] }}</b></div></div></div><div class="c3-cards c3-plan-rows"><article v-for="row in metrics.planView" :key="row.plan.name" class="c3-card c3-accent" :class="'tone-'+PLAN_STATE[row.h.state].c"><header class="c3-card-h"><div><b>{{ row.plan.name }}</b><small>{{ row.plan.category||row.plan.custom_health_status||'Therapy plan' }}</small></div><span class="c3-pill" :class="'tone-'+PLAN_STATE[row.h.state].c">{{ PLAN_STATE[row.h.state].e }} {{ PLAN_STATE[row.h.state].l }}{{ row.h.state==='overdue'?' '+row.h.overdueDays+'d':row.h.state==='behind'?' '+Math.round(row.h.expected-row.h.done)+' short':'' }}</span></header><div class="c3-grid c3-g4"><div v-for="[label,value] in [['Branch',row.plan.branch||'—'],['Start',fdate(row.plan.start_date)],['End date',fdate(row.h.due)+(row.h.estimated?' (est.)':'')],['Consultant',row.plan.custom_employee_name||row.plan.consultant_name||bundle.users[row.plan.owner]||'—'],['Sessions',row.h.done+' / '+row.h.total],['Balance',row.h.balance],['Expected by today',row.h.expected?Math.round(row.h.expected):'—'],['Progress',row.h.pct+'%']]" :key="label" class="c3-kv"><small>{{ label }}</small><b>{{ value }}</b></div></div><span class="c3-meter"><i :class="'tone-'+PLAN_STATE[row.h.state].c" :style="{width:row.h.pct+'%'}"></i></span><div v-if="row.rows.length" class="c3-therapies"><div v-for="therapy in row.rows" :key="therapy.therapy+'|'+therapy.total+'|'+therapy.done" class="c3-th"><b>{{ therapy.therapy }}</b><span>{{ therapy.done }}/{{ therapy.total }}</span><span :class="therapy.balance?'tone-warn':'tone-ok'">{{ therapy.balance }} left</span><span class="c3-meter"><i :style="{width:(therapy.total?Math.round(therapy.done/therapy.total*100):0)+'%'}"></i></span></div></div></article><div v-if="!metrics.planView.length" class="c3-empty-sm">No therapy plans.</div></div></div></template>
